import re
seq="".join(l.strip() for l in open("region.fasta") if not l.startswith(">")).upper()
comp=str.maketrans("ACGT","TGCA")
def rc(s): return s.translate(comp)[::-1]
bases="TCAG"; aas="FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG"
code={}; i=0
for a in bases:
    for b in bases:
        for c in bases:
            code[a+b+c]=aas[i]; i+=1

def allprot(s):
    for f in range(3):
        yield f,"".join(code.get(s[i:i+3],'X') for i in range(f,len(s)-2,3))

# scan for Walker A G..G.GK[ST] everywhere both strands
pat=re.compile(r"G.G.GK[ST]")
for name,s in (("+",seq),("-",rc(seq))):
    for f,p in allprot(s):
        for m in pat.finditer(p):
            # nucleotide position
            if name=="+": nt=f+m.start()*3+1
            else:
                # rc coordinate -> original position: length - (f+m.start()*3) - 3*len ... compute
                nt=len(seq)-(f+m.start()*3)-3*len(m.group())+1
            print(f"{name} frame{f} WalkerA-like {m.group()} at aa {m.start()} nt~{nt}")
print()
# scan for other signatures
